using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using Microsoft.AspNetCore.Mvc.Rendering; using StockWise.Data; using StockWise.Models; using StockWise.ViewModels; using Microsoft.AspNetCore.Authorization;
namespace StockWise.Controllers;
[Authorize] public class SalesController : Controller {private readonly AppDbContext _db;public SalesController(AppDbContext db)=>_db=db; public async Task<IActionResult> Index()=>View(await _db.Sales.OrderByDescending(s=>s.CreatedAtUtc).ToListAsync()); public async Task<IActionResult> Create(){ViewBag.Products=await _db.Products.Where(p=>p.Quantity>0).OrderBy(p=>p.Name).ToListAsync();var vm=new SaleCreateViewModel();var products=(List<Product>)ViewBag.Products;vm.Items=products.Select(p=>new SaleLineInput{ProductId=p.Id,Quantity=0}).ToList();return View(vm);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(SaleCreateViewModel model){var requested=model.Items.Where(i=>i.Quantity>0).GroupBy(i=>i.ProductId).Select(g=>new{ProductId=g.Key,Quantity=g.Sum(x=>x.Quantity)}).ToList();if(!requested.Any())ModelState.AddModelError("Items","Add at least one product with quantity greater than zero.");if(model.DiscountAmount<0)ModelState.AddModelError(nameof(model.DiscountAmount),"Discount cannot be negative.");if(model.TaxPercent<0||model.TaxPercent>100)ModelState.AddModelError(nameof(model.TaxPercent),"Tax must be between 0 and 100 percent.");var products=await _db.Products.Where(p=>requested.Select(x=>x.ProductId).Contains(p.Id)).ToDictionaryAsync(p=>p.Id);foreach(var item in requested){if(!products.ContainsKey(item.ProductId))ModelState.AddModelError("Items","A selected product is invalid.");else if(item.Quantity>products[item.ProductId].Quantity)ModelState.AddModelError("Items",$"Insufficient stock for {products[item.ProductId].Name}. Available: {products[item.ProductId].Quantity}.");}if(!ModelState.IsValid){ViewBag.Products=await _db.Products.Where(p=>p.Quantity>0).OrderBy(p=>p.Name).ToListAsync();return View(model);}await using var tx=await _db.Database.BeginTransactionAsync();foreach(var item in requested){var p=await _db.Products.FirstAsync(x=>x.Id==item.ProductId);if(item.Quantity>p.Quantity){ModelState.AddModelError("Items",$"Stock changed for {p.Name}; try again.");await tx.RollbackAsync();ViewBag.Products=await _db.Products.Where(x=>x.Quantity>0).ToListAsync();return View(model);}}var sale=new Sale{CustomerName=model.CustomerName.Trim(),CreatedAtUtc=DateTime.UtcNow};foreach(var item in requested){var p=products[item.ProductId];sale.Items.Add(new SaleItem{ProductId=p.Id,Quantity=item.Quantity,UnitPrice=p.UnitPrice,LineTotal=p.UnitPrice*item.Quantity});p.Quantity-=item.Quantity;}sale.Subtotal=sale.Items.Sum(i=>i.LineTotal);sale.DiscountAmount=Math.Min(model.DiscountAmount,sale.Subtotal);sale.TaxAmount=Math.Round((sale.Subtotal-sale.DiscountAmount)*model.TaxPercent/100m,2);sale.TotalAmount=sale.Subtotal-sale.DiscountAmount+sale.TaxAmount;_db.Sales.Add(sale);await _db.SaveChangesAsync();sale.InvoiceNumber=$"SW-{sale.Id:D6}";await _db.SaveChangesAsync();await tx.CommitAsync();TempData["Success"]=$"Invoice {sale.InvoiceNumber} created; inventory updated.";return RedirectToAction(nameof(Details),new{id=sale.Id});} public async Task<IActionResult> Details(int? id){if(id==null)return NotFound();var sale=await _db.Sales.Include(s=>s.Items).ThenInclude(i=>i.Product).FirstOrDefaultAsync(s=>s.Id==id);return sale==null?NotFound():View(sale);} }
